{
  "name": "NI数字输入数据采集设备",
  "name_en": "NI Digital Input DAQ Device",
  "manufacturer": "National Instruments",
  "description": "用于采集数字电平和开关量信号的NI数据采集设备或模块，常见于PCIe、USB或cDAQ系统。适合在实验中读取TTL状态、触发信号、联锁状态以及其他数字输入信号。",
  "description_en": "An NI data acquisition device or module used to acquire digital level and on/off signals, commonly found in PCIe, USB, or cDAQ systems. It is used in laboratories to read TTL states, trigger lines, interlock signals, and other digital input signals.",
  "tag_hints": [
    "NI-DAQmx",
    "digital input",
    "DAQ",
    "TTL signals",
    "trigger monitoring",
    "National Instruments"
  ],
  "actions": [
    {
      "action_name": "auto-max_convert_rate",
      "description": "获取最大转换速率",
      "description_en": "Get the maximum conversion rate."
    },
    {
      "action_name": "auto-read_scalar",
      "description": "读取单点数字输入值",
      "description_en": "Read a single digital input value."
    },
    {
      "action_name": "auto-read",
      "description": "读取数字输入数据",
      "description_en": "Read digital input data."
    },
    {
      "action_name": "auto-write",
      "description": "向任务写入数据",
      "description_en": "Write data to the task."
    }
  ]
}

